// ❌ animate*AsState owns the value; there is no way to reset it without motion
@Composable
fun UploadBarWrong(progress: Float) {
  val shown by animateFloatAsState(progress, label = "progress")
  LinearProgressIndicator(progress = { shown })
  // retry sets progress = 0f and the bar slides all the way back
}

// ✅ Animatable: you hold the value and drive it from a coroutine
@Composable
fun UploadBar(progress: Float, attempt: Int) {
  val shown = remember { Animatable(0f) }

  LaunchedEffect(attempt) { shown.snapTo(0f) }          // instant, no animation
  LaunchedEffect(progress) {                            // a new animateTo cancels the old
    shown.animateTo(progress, spring(stiffness = Spring.StiffnessLow))
  }

  LinearProgressIndicator(progress = { shown.value })
}

// ✅ one state change, several values that must stay in lockstep
@Composable
fun FilterChip(selected: Boolean, label: String) {
  val t = updateTransition(selected, label = "chip")
  val border by t.animateDp(label = "border") { if (it) 2.dp else 1.dp }
  val alpha by t.animateFloat(label = "alpha") { if (it) 1f else 0.6f }
  val color by t.animateColor(label = "color") {
    if (it) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline
  }
  Box(
    Modifier
      .border(border, color, CircleShape)
      .graphicsLayer { this.alpha = alpha },
  ) { Text(label) }
}

// ❌ the lambda ignores its parameter and reads the captured count, so the leaving
//    copy re-renders with the new number and the crossfade is invisible
AnimatedContent(targetState = count, label = "total") {
  Text("Total: $count")
}

// ✅ render the state THIS piece of content was composed for
AnimatedContent(
  targetState = count,
  label = "total",
  transitionSpec = {
    if (targetState > initialState) {
      slideInVertically { h -> h } + fadeIn() togetherWith
        slideOutVertically { h -> -h } + fadeOut()
    } else {
      slideInVertically { h -> -h } + fadeIn() togetherWith
        slideOutVertically { h -> h } + fadeOut()
    }.using(SizeTransform(clip = false))   // null here makes the box jump instead
  },
) { target ->
  Text("Total: $target")
}

// children stay composed until the exit finishes, and can stagger their own motion
AnimatedVisibility(
  visible = expanded,
  enter = fadeIn() + expandVertically(),
  exit = fadeOut() + shrinkVertically(),
) {
  Column {
    Text(item.details)
    Icon(
      Icons.Default.Star,
      contentDescription = null,
      modifier = Modifier.animateEnterExit(enter = scaleIn(), exit = scaleOut()),
    )
  }
}

// animate on first composition — a plain Boolean starts already visible
val state = remember { MutableTransitionState(false) }.apply { targetState = true }
AnimatedVisibility(visibleState = state, enter = slideInHorizontally()) { Banner() }

@Composable
fun TaskList(tasks: List<Task>, onToggle: (String) -> Unit) {
  LazyColumn {
    items(
      items = tasks,
      key = { it.id },            // stable, unique, saveable — this is the mechanism
      contentType = { it.kind },  // reuse a matching slot in a mixed list
    ) { task ->
      TaskRow(
        task = task,
        onToggle = { onToggle(task.id) },
        modifier = Modifier
          .animateItem(           // placement + fade in + fade out
            placementSpec = spring(stiffness = Spring.StiffnessMediumLow),
          )
          .fillMaxWidth(),
      )
    }
  }
}

// ❌ no key: items are identified by index, so a sort moves nothing
items(tasks) { task -> TaskRow(task, Modifier.animateItem()) }

// ❌ key derived from mutable content: an edit looks like delete + insert
items(tasks, key = { it.hashCode() }) { task -> TaskRow(task) }

// ❌ modifier applied inside the item instead of on its root — nothing animates
items(tasks, key = { it.id }) { task ->
  Row { Text(task.title, Modifier.animateItem()) }
}

// animateItem does not cover the item's OWN size changing
items(tasks, key = { it.id }) { task ->
  Column(Modifier.animateItem().animateContentSize()) {
    Text(task.title)
    if (task.id in expanded) Text(task.notes)
  }
}

