// a curve the designer specified — fixed duration, exact easing
val alpha by animateFloatAsState(
  targetValue = if (visible) 1f else 0f,
  animationSpec = tween(durationMillis = 300, easing = CubicBezierEasing(0.2f, 0f, 0f, 1f)),
  label = "alpha",
)

// movement that can be interrupted — the spring carries velocity into the retarget
val offset by animateDpAsState(
  targetValue = if (expanded) 0.dp else 120.dp,
  animationSpec = spring(
    dampingRatio = Spring.DampingRatioLowBouncy,
    stiffness = Spring.StiffnessMediumLow,
  ),
  label = "offset",
)

// multi-stage motion: overshoot, then settle
val scale by animateFloatAsState(
  targetValue = if (pressed) 1f else 0.9f,
  animationSpec = keyframes {
    durationMillis = 375
    0.9f at 0 using LinearOutSlowInEasing
    1.08f at 250
    1f at 375
  },
  label = "scale",
)

// ❌ a bare Animatable holding pixels keeps ticking below one pixel of movement
val loose = remember { Animatable(0f) }              // threshold defaults to 0.01f

// ✅ tell the spring when it is close enough to stop
val pixels = remember { Animatable(0f, visibilityThreshold = 0.5f) }

// typed values already carry the right threshold
val height = remember { Animatable(0.dp, Dp.VectorConverter) }

@Composable
fun CoastingCard(modifier: Modifier = Modifier) {
  val offsetX = remember { Animatable(0f) }

  Box(
    modifier
      .offset { IntOffset(offsetX.value.roundToInt(), 0) }  // read in layout, not composition
      .pointerInput(Unit) {
        val decay = splineBasedDecay<Float>(this)
        offsetX.updateBounds(-size.width.toFloat(), size.width.toFloat())
        coroutineScope {
          while (true) {
            val down = awaitPointerEventScope { awaitFirstDown() }
            offsetX.stop()                    // seize the value from a running fling
            val tracker = VelocityTracker()
            awaitPointerEventScope {
              horizontalDrag(down.id) { change ->
                launch { offsetX.snapTo(offsetX.value + change.positionChange().x) }
                tracker.addPosition(change.uptimeMillis, change.position)
                change.consume()              // tell the scrolling parent to back off
              }
            }
            val velocity = tracker.calculateVelocity().x
            val landing = decay.calculateTargetValue(offsetX.value, velocity)
            launch {
              if (abs(landing) < size.width / 3f) {
                offsetX.animateTo(0f, spring(), initialVelocity = velocity)  // keep the throw
              } else {
                offsetX.animateDecay(velocity, decay)                        // coast out
              }
            }
          }
        }
      },
  ) { CardBody() }
}

// ❌ the value in plain state: no velocity, no interruption, no bounds —
//    onDragEnd has nothing to hand to the next animation
var x by remember { mutableFloatStateOf(0f) }

// ❌ pointerInput(Unit) captures onSelect once and never sees a newer one
Modifier.pointerInput(Unit) {
  detectTapGestures(onLongPress = { onSelect(item.id) })
}

// ❌ keying on the lambda restarts the coroutine whenever its identity changes —
//    an unmemoised lambda cancels the gesture the user is making right now
Modifier.pointerInput(onSelect) {
  detectTapGestures(onLongPress = { onSelect(item.id) })
}

// ✅ keep the coroutine alive, always read the latest lambda
@Composable
fun SelectableRow(item: Item, onSelect: (String) -> Unit) {
  val select by rememberUpdatedState(onSelect)
  Box(
    Modifier
      .padding(8.dp)               // padding BEFORE pointerInput is not touchable
      .pointerInput(item.id) {     // key on something stable, if at all
        detectTapGestures(onLongPress = { select(item.id) })
      },
  ) { RowBody(item) }
}

// the raw loop the detect* helpers are built on
Modifier.pointerInput(Unit) {
  awaitPointerEventScope {
    while (true) {
      val down = awaitFirstDown()
      val slop = awaitTouchSlopOrCancellation(down.id) { change, _ -> change.consume() }
      if (slop != null) {
        drag(slop.id) { change ->
          onDrag(change.positionChange())
          change.consume()         // consumed: the built-in detectors skip this change
        }
      }
    }
  }
}

// a parent that must intercept listens before its children get the event
Modifier.pointerInput(Unit) {
  awaitPointerEventScope {
    while (true) {
      val event = awaitPointerEvent(PointerEventPass.Initial)
      if (shouldIntercept(event)) event.changes.forEach { it.consume() }
    }
  }
}

// ❌ a tap listener and nothing else: no ripple, no semantics, not focusable
Box(
  Modifier.pointerInput(Unit) {
    detectTapGestures(onTap = { open() }, onDoubleTap = { like() })
  },
) { PostBody() }

// ✅ the extra gestures, with indication, semantics and focus intact
Box(
  Modifier
    .clip(MaterialTheme.shapes.medium)     // clip first, or the ripple is a rectangle
    .combinedClickable(
      onClick = open,
      onDoubleClick = like,
      onLongClick = showMenu,
      onClickLabel = "Open the post",      // TalkBack: "double-tap to Open the post"
      role = Role.Button,
    ),
) { PostBody() }

// a 24dp glyph: padding INSIDE the clickable makes the node measure 48dp
Icon(
  imageVector = Icons.Default.Close,
  contentDescription = "Dismiss",
  modifier = Modifier
    .clickable(onClick = onDismiss)
    .padding(12.dp)
    .size(24.dp),
)

// if raw pointer input really is unavoidable, put the missing pieces back
val interaction = remember { MutableInteractionSource() }
Box(
  Modifier
    .indication(interaction, ripple())
    .semantics { onClick(label = "Crop") { crop(); true } }
    .pointerInput(Unit) {
      detectTapGestures(
        onPress = { offset ->
          val press = PressInteraction.Press(offset)
          interaction.emit(press)
          tryAwaitRelease()
          interaction.emit(PressInteraction.Release(press))
        },
        onTap = { crop() },
      )
    },
) { CropHandle() }

enum class Swipe { Settled, Dismissed }

@Composable
fun SwipeToDeleteRow(item: Item, onDelete: () -> Unit) {
  val density = LocalDensity.current
  val decay = rememberSplineBasedDecay<Float>()
  val state = remember {
    AnchoredDraggableState(
      initialValue = Swipe.Settled,
      positionalThreshold = { distance -> distance * 0.5f },
      velocityThreshold = { with(density) { 125.dp.toPx() } },
      snapAnimationSpec = spring(),
      decayAnimationSpec = decay,
    )
  }

  // the row leaves the list when the animation LANDS, not when the target is chosen
  LaunchedEffect(state.settledValue) {
    if (state.settledValue == Swipe.Dismissed) onDelete()
  }

  Box(
    Modifier
      .fillMaxWidth()
      .onSizeChanged { size ->                     // anchors need the measured width
        state.updateAnchors(
          DraggableAnchors {
            Swipe.Settled at 0f
            Swipe.Dismissed at -size.width.toFloat()
          }
        )
      }
      .anchoredDraggable(state, Orientation.Horizontal),
  ) {
    DeleteBackground()
    Surface(
      // reading state.requireOffset() out here, in composition, would recompose
      // the row on every frame of the drag; the lambda defers it to placement
      Modifier.offset { IntOffset(state.requireOffset().roundToInt(), 0) },
    ) {
      RowContent(item)
    }
  }
}

class CollapsingHeaderConnection(private val maxOffsetPx: Float) : NestedScrollConnection {

  var offset by mutableFloatStateOf(0f)   // -maxOffsetPx..0f
    private set

  // going up: the header shrinks BEFORE the list scrolls
  override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
    if (available.y >= 0f) return Offset.Zero
    val previous = offset
    offset = (offset + available.y).coerceIn(-maxOffsetPx, 0f)
    return Offset(0f, offset - previous)
  }

  // coming back: only what the list left over, i.e. once it is at the very top
  override fun onPostScroll(
    consumed: Offset,
    available: Offset,
    source: NestedScrollSource,
  ): Offset {
    if (available.y <= 0f) return Offset.Zero
    val previous = offset
    offset = (offset + available.y).coerceIn(-maxOffsetPx, 0f)
    return Offset(0f, offset - previous)
  }
}

@Composable
fun FeedScreen(items: List<Item>) {
  val maxOffset = with(LocalDensity.current) { 160.dp.toPx() }
  val connection = remember(maxOffset) { CollapsingHeaderConnection(maxOffset) }

  Box(Modifier.nestedScroll(connection)) {
    LazyColumn(contentPadding = PaddingValues(top = 160.dp)) {
      items(items, key = { it.id }) { FeedRow(it) }
    }
    // read in the draw phase: scrolling redraws the header, it does not recompose it
    Header(Modifier.graphicsLayer { translationY = connection.offset })
  }
}

// wrong: claims the gesture the moment slop is crossed in ANY direction,
// so the LazyColumn underneath never sees a vertical drag
Modifier.pointerInput(Unit) {
  detectDragGestures { change, drag ->
    change.consume()
    offsetX += drag.x
  }
}

// right: only horizontal movement is claimed, vertical falls through to the list
Modifier.pointerInput(Unit) {
  detectHorizontalDragGestures { change, dragAmount ->
    change.consume()
    offsetX += dragAmount
  }
}

// better: draggable is orientation-aware and cooperates with nested scroll
Modifier.draggable(
  orientation = Orientation.Horizontal,
  state = rememberDraggableState { delta -> offsetX += delta },
)

// a parent that must take the event before its children: the Initial pass
Modifier.pointerInput(locked) {
  awaitEachGesture {
    val down = awaitPointerEvent(PointerEventPass.Initial).changes.first()
    if (locked) down.consume()          // children are never offered it
  }
}

// the Final pass is where you find out somebody else took the gesture
Modifier.pointerInput(Unit) {
  awaitEachGesture {
    awaitFirstDown(requireUnconsumed = false)
    do {
      val event = awaitPointerEvent(PointerEventPass.Final)
      if (event.changes.any { it.isConsumed }) clearPressedHighlight()
    } while (event.changes.any { it.pressed })
  }
}

@Composable
fun FadingStack(fade: Float) {
  // wrong: alpha per drawing instruction, so the circles show through each other
  Box(
    Modifier.graphicsLayer {
      alpha = fade
      compositingStrategy = CompositingStrategy.ModulateAlpha
    }
  ) { OverlappingCircles() }

  // right: draw the group into one buffer, then fade the buffer
  Box(
    Modifier.graphicsLayer {
      alpha = fade
      compositingStrategy = CompositingStrategy.Offscreen  // also clips to the bounds
    }
  ) { OverlappingCircles() }
}

@Composable
fun ParallaxHeader(listState: LazyListState) {
  // wrong: the offset is read in composition — every scrolled frame recomposes Header
  Header(Modifier.graphicsLayer(translationY = listState.firstVisibleItemScrollOffset * -0.5f))

  // right: the lambda runs in the draw phase — redraw only, no recomposition, no layout
  Header(
    Modifier.graphicsLayer {
      translationY = listState.firstVisibleItemScrollOffset * -0.5f
    }
  )
}

// shadow, shape, clipping and the pivot of a rotation all live on the same layer
fun Modifier.flipCard(spin: Float) = graphicsLayer {
  shadowElevation = 8.dp.toPx()
  shape = RoundedCornerShape(16.dp)
  clip = true
  rotationY = spin
  cameraDistance = 12f * density
  transformOrigin = TransformOrigin(0.5f, 1f)   // rotate about the bottom edge
}

@Composable
fun Gauge(progress: Float, modifier: Modifier = Modifier) {
  val sweep by animateFloatAsState(progress * 270f, label = "sweep")

  Box(
    modifier
      .size(160.dp)
      .drawWithCache {
        // runs on a size change, not on a frame: build the expensive things here
        val stroke = Stroke(width = 12.dp.toPx(), cap = StrokeCap.Round)
        val brush = Brush.sweepGradient(listOf(Color(0xFF00C853), Color(0xFFFFD600)))
        val inset = stroke.width / 2f
        val arcSize = Size(size.width - stroke.width, size.height - stroke.width)

        onDrawBehind {
          // the animated value is read HERE — reading it above would rebuild the
          // cache on every frame and defeat the entire modifier
          drawArc(
            brush = brush,
            startAngle = 135f,
            sweepAngle = sweep,
            useCenter = false,
            topLeft = Offset(inset, inset),
            size = arcSize,
            style = stroke,
          )
        }
      }
  )
}

// the same drawing, allocating a brush and a stroke on every single frame
fun Modifier.wastefulGauge(sweep: Float) = drawBehind {
  drawArc(
    brush = Brush.sweepGradient(listOf(Color.Green, Color.Yellow)),
    startAngle = 135f,
    sweepAngle = sweep,
    useCenter = false,
    style = Stroke(width = 12.dp.toPx(), cap = StrokeCap.Round),
  )
}

// laid-out text is expensive too, so it belongs in the cache block as well
@Composable
fun Modifier.percentLabel(measurer: TextMeasurer, text: String) = drawWithCache {
  val laid = measurer.measure(AnnotatedString(text), TextStyle(fontSize = 24.sp))
  onDrawWithContent {
    drawContent()
    drawText(laid, topLeft = Offset(24f, 24f))
  }
}

@Composable
fun FrostedPanel(modifier: Modifier = Modifier, content: @Composable BoxScope.() -> Unit) {
  val canBlur = Build.VERSION.SDK_INT >= Build.VERSION_CODES.S    // API 31

  Box(modifier.clip(RoundedCornerShape(24.dp))) {
    Wallpaper(
      // below API 31 Modifier.blur is a no-op, so it can never be the only styling
      if (canBlur) Modifier.blur(24.dp, BlurredEdgeTreatment.Unbounded) else Modifier
    )
    if (!canBlur) {
      // the fallback is a design decision, not an empty branch
      Box(
        Modifier
          .matchParentSize()
          .background(
            Brush.verticalGradient(
              listOf(Color.Black.copy(alpha = 0.30f), Color.Black.copy(alpha = 0.60f))
            )
          )
      )
    }
    content()
  }
}

// animate the fade of a fixed-radius blur, never the radius itself
fun Modifier.revealBlur(reveal: Float) = graphicsLayer {
  renderEffect = BlurEffect(radiusX = 24f, radiusY = 24f, edgeTreatment = TileMode.Decal)
  alpha = reveal
}

// AGSL: Android 13 and up only
@RequiresApi(Build.VERSION_CODES.TIRAMISU)
fun shimmerBrush(size: Size, time: Float): Brush {
  val shader = RuntimeShader(
    """
    uniform float2 resolution;
    uniform float time;
    half4 main(float2 coord) {
      float t = coord.x / resolution.x + time;
      float wave = t - floor(t);
      return half4(wave, 0.7, 1.0 - wave, 1.0);
    }
    """.trimIndent()
  )
  shader.setFloatUniform("resolution", size.width, size.height)
  shader.setFloatUniform("time", time)
  return ShaderBrush(shader)
}

@OptIn(ExperimentalSharedTransitionApi::class)
@Composable
fun Gallery(items: List<Item>, grid: Boolean) {
  LookaheadScope {
    FlowRow(maxItemsInEachRow = if (grid) 2 else 1) {
      items.forEach { item ->
        key(item.id) {
          // animateBounds animates size AND position between the two arrangements
          Card(Modifier.animateBounds(lookaheadScope = this@LookaheadScope)) {
            ItemContent(item)
          }
        }
      }
    }
  }
}

// the same idea by hand, when you need control over the spec or the constraints
@Composable
fun Modifier.approachSize(): Modifier {
  val scope = rememberCoroutineScope()
  val sizeAnim = remember { Animatable(IntSize.Zero, IntSize.VectorConverter) }

  return approachLayout(
    isMeasurementApproachInProgress = { lookaheadSize ->
      // the lookahead pass already knows where this node is going
      if (lookaheadSize != sizeAnim.targetValue) {
        scope.launch { sizeAnim.animateTo(lookaheadSize, spring(stiffness = 200f)) }
      }
      sizeAnim.isRunning          // false here hands the node back to the fast path
    }
  ) { measurable, _ ->
    val target = sizeAnim.value
    val placeable = measurable.measure(Constraints.fixed(target.width, target.height))
    layout(placeable.width, placeable.height) { placeable.place(0, 0) }
  }
}

// wrong: an animation driven from a scope that carries no MotionDurationScale.
// It plays at full length even when the user has turned animations off.
class CardViewModel : ViewModel() {
  val reveal = Animatable(0f)
  fun onOpen() = viewModelScope.launch { reveal.animateTo(1f, tween(400)) }
}

// right: let the composition own it — animate*AsState inherits the duration scale
@Composable
fun Card(open: Boolean) {
  val reveal by animateFloatAsState(
    targetValue = if (open) 1f else 0f,
    animationSpec = tween(400),
    label = "reveal",
  )
  Box(Modifier.graphicsLayer { alpha = reveal; translationY = (1f - reveal) * 48f })
}

// loops have no target to snap to, so ask the system yourself
val LocalAnimationsEnabled = staticCompositionLocalOf { true }

@Composable
fun rememberAnimationsEnabled(): Boolean {
  val context = LocalContext.current
  // re-read on resume if the user may change it while the app is open
  return remember(context) {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
      ValueAnimator.areAnimatorsEnabled()
    } else {
      Settings.Global.getFloat(
        context.contentResolver,
        Settings.Global.ANIMATOR_DURATION_SCALE,
        1f,
      ) != 0f
    }
  }
}

@Composable
fun ShimmerPlaceholder() {
  if (!LocalAnimationsEnabled.current) {
    Box(Modifier.background(Color.LightGray))   // the still frame, not a loop
    return
  }
  val transition = rememberInfiniteTransition(label = "shimmer")
  val x by transition.animateFloat(
    initialValue = 0f,
    targetValue = 1f,
    animationSpec = infiniteRepeatable(tween(1200)),
    label = "x",
  )
  Box(Modifier.drawBehind { drawShimmer(x) })
}

@get:Rule val rule = createComposeRule()

@Test fun cardIsHalfwayAt200ms() {
  // the test clock is virtual and ignores the device setting entirely; stop it
  // and step it by hand, or waitForIdle never returns on the shimmer above
  rule.mainClock.autoAdvance = false
  rule.setContent { Card(open = true) }
  rule.mainClock.advanceTimeBy(200)
  rule.onNodeWithTag("card").assertIsDisplayed()
}
